'use strict';
const STUDENT_ITEMS=[
{id:'snack',name:'Emergency snack',icon:'🥪',price:350,kind:'food',text:'+22 hunger, +3 mood. Keep it for a busy day.',effect:{hunger:22,mood:3}},
{id:'water',name:'Water bottle refill',icon:'💧',price:100,kind:'food',text:'+6 energy, +4 mood. A small reset between classes.',effect:{energy:6,mood:4}},
{id:'noodles',name:'Hostel noodles',icon:'🍜',price:450,kind:'food',text:'+32 hunger. Prepare it when you are back at a hostel.',effect:{hunger:32}},
{id:'soap',name:'Toiletry kit',icon:'🧼',price:400,kind:'care',text:'Three extra freshen-up boosts.',uses:3},
{id:'casual',name:'Campus casual',icon:'👕',price:800,kind:'outfit',text:'A relaxed outfit for your campus profile.'},
{id:'smart',name:'Presentation day',icon:'👔',price:1500,kind:'outfit',text:'Dress up your profile for a big day.'},
{id:'sport',name:'Match-day kit',icon:'🎽',price:1100,kind:'outfit',text:'Your sporting side, on your profile.'},
{id:'desk',name:'Study desk & lamp',icon:'💡',price:2000,kind:'room',text:'+2 knowledge for study and project sessions.'},
{id:'bed',name:'Comfortable bedding',icon:'🛏️',price:2400,kind:'room',text:'+10 energy from naps; wake up with +8 energy.'},
{id:'plants',name:'Plants & wall prints',icon:'🪴',price:900,kind:'room',text:'+4 mood when a new day begins.'}
];
const STUDENT_GIGS=[{id:'tutor',title:'Peer tutoring',icon:'📚',skill:0,hours:2,pay:1000,energy:-14,text:'Explain a topic to a fictional coursemate.'},{id:'design',title:'Design a society flyer',icon:'🎨',skill:20,hours:2,pay:1600,energy:-15,text:'Help a fictional student society announce its event.'},{id:'web',title:'Build a club webpage',icon:'💻',skill:45,hours:3,pay:2600,energy:-22,text:'Create a small webpage for a fictional club.'}];
const STUDENT_CLUBS=[{id:'code',name:'Code & Create',icon:'💻',text:'Build small projects with fictional campus makers.',effect:{skills:10,knowledge:3,social:8,energy:-12}},{id:'sport',name:'Campus Athletics',icon:'⚽',text:'Train together and celebrate little improvements.',effect:{mood:14,social:10,energy:-17,hunger:-8}},{id:'arts',name:'Creative Circle',icon:'🎨',text:'Art, performance and room for your next idea.',effect:{skills:6,mood:12,social:10,energy:-10}},{id:'service',name:'Community Crew',icon:'🌱',text:'Plan fictional community activities with your peers.',effect:{skills:5,mood:10,social:12,energy:-11}}];
const QUIZ_BANK=[{q:'A strong academic source should be evaluated for…',a:['Credibility and relevance','How colourful it looks','Whether it agrees with you'],correct:0},{q:'Which approach usually supports long-term recall?',a:['One all-night session','Spaced practice with retrieval','Rereading only the title'],correct:1},{q:'What is a useful first step before starting a project?',a:['Write the conclusion','Ignore the marking criteria','Clarify the problem and requirements'],correct:2},{q:'How should you use another author’s ideas?',a:['Cite the source accurately','Change one word only','Remove the author’s name'],correct:0},{q:'What does a budget help you compare?',a:['Your GPA and your height','Expected income and planned spending','Your friends’ passwords'],correct:1},{q:'A good group-project plan should include…',a:['Tasks, owners and deadlines','Only a group chat name','One person doing everything'],correct:0}];
const academicBuilding=()=>({Engineering:'engineering',Medicine:'medicine',Nursing:'medicine',Law:'law',Pharmacy:'pharmacy','Business Administration':'social',Agriculture:'lecture'}[state.course]||'lecture');
function studentTick(){return (state.day-1)*14+Math.max(0,state.hour-8)}
function ensureStudentState(){if(!state)return null;if(!state.student||typeof state.student!=='object')state.student={};const s=state.student;const defaults={hygiene:85,bladder:85,savings:0,inventory:{},owned:[],outfit:'default',club:null,clubPoints:0,reputation:0,projects:{},quizDays:[],eventDays:[],achievements:[],ledger:[],cashCheckpoint:state.money,tick:studentTick(),notices:[],scholarship:false,phoneApp:'home',profileBio:'Finding my way, one campus day at a time.'};for(const[k,v]of Object.entries(defaults))if(s[k]===undefined)s[k]=v;
for(const key of ['hygiene','bladder'])s[key]=clamp(Number.isFinite(s[key])?s[key]:85);if(!Number.isFinite(s.savings)||s.savings<0)s.savings=0;return s}
function syncStudentLife(){if(!state)return;const s=ensureStudentState(),tick=studentTick(),elapsed=Math.max(0,tick-s.tick);if(elapsed){s.hygiene=clamp(s.hygiene-elapsed*2);s.bladder=clamp(s.bladder-elapsed*3);state.social=clamp(state.social-elapsed*1.3);if(s.hygiene<15||s.bladder<15)state.mood=clamp(state.mood-Math.min(6,elapsed));s.tick=tick}if(state.money!==s.cashCheckpoint){s.ledger.unshift({day:state.day,hour:state.hour,amount:state.money-s.cashCheckpoint,text:state.logs[0]?.text||'Game wallet activity'});s.ledger=s.ledger.slice(0,100);s.cashCheckpoint=state.money}for(const p of projectList()){const work=s.projects[p.id];if(state.day>p.due&&!work?.submitted&&!work?.missed){s.projects[p.id]={...work,missed:true};s.reputation=Math.max(0,s.reputation-2);notifyStudent(p.title+' deadline passed. Future projects are still available.');log('Missed the fictional deadline for '+p.title+'.')}}awardStudentAchievements()}
function notifyStudent(text){const s=ensureStudentState();s.notices.unshift({day:state.day,text});s.notices=s.notices.slice(0,30)}
function projectList(){return[{id:'p1',title:'Foundations assignment',due:7},{id:'p2',title:'Team research brief',due:14},{id:'p3',title:'Practical portfolio',due:21},{id:'p4',title:'Semester presentation',due:27}]}
function studentNight(){const s=ensureStudentState();if(s.owned.includes('bed'))state.energy=clamp(state.energy+8);if(s.owned.includes('plants'))state.mood=clamp(state.mood+4);s.bladder=clamp(s.bladder+20)}
function studentActionEffect(p,a){const s=ensureStudentState();if(/nap$/.test(a[0])&&s.owned.includes('bed'))state.energy=clamp(state.energy+10);if(/study|project|research|assignment/.test(a[0])&&s.owned.includes('desk'))state.knowledge=clamp(state.knowledge+2);if(/wash$/.test(a[0]))s.hygiene=clamp(s.hygiene+45)}
function awardStudentAchievements(){const s=ensureStudentState();const checks=[['firstlecture','First lecture',state.attendance>=1],['saver','A little safety net',s.savings>=3000],['home','A room of my own',s.owned.filter(id=>STUDENT_ITEMS.find(i=>i.id===id)?.kind==='room').length>=2],['club','Found my community',s.clubPoints>=3],['deadlines','Ahead of the deadline',Object.values(s.projects).filter(p=>p.submitted).length>=2],['scholar','Scholarship ready',s.scholarship],['friendship','A friend to count on',state.friends.some(x=>x>=3)],['explorer','Campus explorer',state.visits.filter(id=>places.some(p=>p.id===id&&p.mapped)).length>=10]];for(const[id,name,done]of checks)if(done&&!s.achievements.includes(id)){s.achievements.push(id);notifyStudent('Achievement unlocked: '+name);s.reputation+=3}}
function studentCommit(text,app){log(text);syncStudentLife();save();render();ping();toast(text);if(app)openStudentPhone(app)}
function isHostel(){return places.find(p=>p.id===state.location)?.type==='hostel'}
function studentSpendTime(hours,energy=-5,cost=0){if(!checkTime(hours,energy,cost))return false;state.hour+=hours;state.money-=cost;state.energy=clamp(state.energy+energy);state.hunger=clamp(state.hunger-hours*2);return true}
function buyStudentItem(id){const item=STUDENT_ITEMS.find(x=>x.id===id),s=ensureStudentState();if(!item||state.finished)return;if(['room','outfit'].includes(item.kind)&&s.owned.includes(id)){toast('You already own that item.');return}if((s.inventory[id]||0)>=10){toast('Your bag has enough of that item.');return}if(!checkTime(0,0,item.price))return;state.money-=item.price;if(['room','outfit'].includes(item.kind))s.owned.push(id);else s.inventory[id]=(s.inventory[id]||0)+(item.uses||1);studentCommit('Bought '+item.name+' for '+money(item.price)+'.','shop')}
function useStudentItem(id){const s=ensureStudentState(),item=STUDENT_ITEMS.find(i=>i.id===id);if(!item||state.finished||(s.inventory[id]||0)<1)return;if(id==='noodles'&&!isHostel()){toast('Head to a hostel to prepare your noodles.');return}if(!studentSpendTime(1,0))return;s.inventory[id]--;if(id==='soap')s.hygiene=clamp(s.hygiene+45);else effect(item.effect);studentCommit('Used '+item.name+'.','bag')}
function equipStudentOutfit(id){const s=ensureStudentState();if(state.finished||!['default',...s.owned].includes(id))return;if(id!=='default'&&STUDENT_ITEMS.find(x=>x.id===id)?.kind!=='outfit')return;s.outfit=id;studentCommit('Changed campus outfit.','wardrobe')}
function studentCare(kind){const s=ensureStudentState();if(state.finished)return;if(kind==='shower'&&!isHostel()){toast('Travel to a hostel for a shower.');return}if(!studentSpendTime(1,kind==='rest'?0:-2))return;syncStudentLife();if(kind==='shower'){s.hygiene=100;state.mood=clamp(state.mood+7)}if(kind==='bathroom')s.bladder=100;if(kind==='rest'){state.mood=clamp(state.mood+12);state.energy=clamp(state.energy+6)}studentCommit(kind==='shower'?'Showered and freshened up.':kind==='bathroom'?'Took a bathroom break.':'Took a quiet wellbeing break.','needs')}
function studentSavings(direction,raw){const amount=Number(raw),s=ensureStudentState();if(state.finished||!Number.isSafeInteger(amount)||amount<=0||amount>1000000){toast('Enter a whole amount above zero.');return}if(direction==='deposit'){if(state.money<amount){toast('Your wallet does not have enough virtual naira.');return}state.money-=amount;s.savings+=amount}else{if(s.savings<amount){toast('Your savings balance is too low.');return}s.savings-=amount;state.money+=amount}studentCommit((direction==='deposit'?'Moved ':'Withdrew ')+money(amount)+(direction==='deposit'?' to virtual savings.':' from virtual savings.'),'wallet')}
function studentGig(id){const s=ensureStudentState(),g=STUDENT_GIGS.find(x=>x.id===id);if(!g||state.finished)return;if(state.daily.studentGig){toast('One student gig per game day. Come back tomorrow.');return}if(state.skills<g.skill){toast('Build your skills to '+g.skill+' first.');return}if(!studentSpendTime(g.hours,g.energy))return;state.money+=g.pay;state.skills=clamp(state.skills+6);s.reputation+=2;state.daily.studentGig=true;studentCommit('Completed '+g.title+' and earned '+money(g.pay)+'.','gigs')}
function joinStudentClub(id){const s=ensureStudentState();if(state.finished||s.club){toast('You already belong to a club this semester.');return}if(!STUDENT_CLUBS.some(x=>x.id===id))return;s.club=id;studentCommit('Joined '+STUDENT_CLUBS.find(x=>x.id===id).name+'.','clubs')}
function meetStudentClub(){const s=ensureStudentState(),c=STUDENT_CLUBS.find(x=>x.id===s.club);if(!c||state.finished)return;if(state.daily.club){toast('You have attended your club meetup today.');return}if(!studentSpendTime(2,c.effect.energy))return;const e={...c.effect};delete e.energy;effect(e);s.clubPoints++;state.daily.club=true;studentCommit('Attended '+c.name+' meetup.','clubs')}
function workStudentProject(id){const s=ensureStudentState(),p=projectList().find(x=>x.id===id),work=s.projects[id]||{progress:0};if(!p||state.finished||state.day>p.due||work.submitted){toast('This project is closed.');return}if((work.progress||0)>=2){toast('The work is ready. Submit it before the deadline.');return}if(!studentSpendTime(2,-13))return;work.progress=(work.progress||0)+1;s.projects[id]=work;state.knowledge=clamp(state.knowledge+5+(s.owned.includes('desk')?2:0));studentCommit('Worked on '+p.title+'.','planner')}
function submitStudentProject(id){const s=ensureStudentState(),p=projectList().find(x=>x.id===id),work=s.projects[id];if(!p||state.finished||state.day>p.due||!work||work.progress<2||work.submitted){toast('Complete two work sessions and submit before the deadline.');return}if(!studentSpendTime(1,-3))return;work.submitted=true;state.assignments++;state.knowledge=clamp(state.knowledge+7);s.reputation+=5;studentCommit('Submitted '+p.title+' before its deadline.','planner')}
function claimStudentScholarship(){const s=ensureStudentState();if(state.finished||s.scholarship)return;if(gpa()<3.5||state.attendance<8||!Object.values(s.projects).some(p=>p.submitted)){toast('Reach GPA 3.50, attend 8 lectures and submit a planner project first.');return}s.scholarship=true;state.money+=5000;studentCommit('Earned the fictional campus merit award: ₦5,000.','wallet')}
function studentEvent(){const s=ensureStudentState(),day=state.day;if(![5,12,19,26].includes(day)||state.hour<16||state.hour>19){toast('Student showcase: days 5, 12, 19 and 26, 16:00–20:00.');return}if(s.eventDays.includes(day)){toast('You already attended this showcase.');return}if(!studentSpendTime(1,-6,200))return;s.eventDays.push(day);state.mood=clamp(state.mood+18);state.social=clamp(state.social+15);s.reputation+=3;studentCommit('Joined the fictional weekly student showcase.','planner')}
function studentMessage(i,choice){if(!Number.isInteger(i)||!people[i]||state.finished)return;if(state.daily['message'+i]){toast('You have already replied to this friend today.');return}if(!studentSpendTime(1,-4))return;state.daily['message'+i]=true;state.social=clamp(state.social+10);state.mood=clamp(state.mood+7);state.friends[i]=Math.min(5,state.friends[i]+1);if(choice==='study')state.knowledge=clamp(state.knowledge+4);else if(choice==='create')state.skills=clamp(state.skills+4);studentCommit('Replied to '+people[i].name+' and made time to connect.','messages')}
function startStudentQuiz(){const s=ensureStudentState();if(state.finished||s.quizDays.includes(state.day)){toast('One revision quiz per day.');return}if(!studentSpendTime(1,-6))return;s.quizDays.push(state.day);const questions=[0,1,2].map(i=>QUIZ_BANK[(state.day+i-1)%QUIZ_BANK.length]);let index=0,score=0;function draw(){const q=questions[index];show(`<div class="eyebrow">REVISION PRACTICE · ${index+1} / 3</div><h2>${q.q}</h2><p>Choose one answer. This is fictional general study practice, not an ABUAD exam.</p>${q.a.map((a,i)=>`<button class="secondary" data-answer="${i}">${escapeHtml(a)}</button>`).join('')}`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.answer)===q.correct)score++;index++;if(index<questions.length)draw();else{state.knowledge=clamp(state.knowledge+score*3);ensureStudentState().reputation+=score;studentCommit('Completed revision practice: '+score+'/3 correct.','planner')}})}log('Started today’s revision quiz.');save();render();draw()}
const PHONE_APPS=[['planner','📅','Planner','Your class, your deadlines.'],['wallet','💳','Wallet','Allowance, savings & a little discipline.'],['needs','🌿','Wellbeing','Make room for yourself.'],['messages','💬','Messages','Fictional friends. Real game choices.'],['gigs','💻','Student gigs','Earn around your studies.'],['shop','🛍️','Campus shop','A bag ready for the day.'],['bag','🎒','My bag','Use what you brought along.'],['room','🛏️','My hostel','Make your corner feel like home.'],['wardrobe','👕','Wardrobe','Show up in your own style.'],['clubs','🤝','Societies','Find your people.'],['achievements','🏅','Milestones','Little wins that add up.'],['settings','⚙️','My profile','Your name. Your campus story.']];
function phoneButton(label,attr,disabled=false){return `<button class="secondary" ${attr} ${disabled||state.finished?'disabled':''}>${label}</button>`}
function openStudentPhone(app='home'){const s=ensureStudentState();s.phoneApp=app;const meta=PHONE_APPS.find(a=>a[0]===app);show(`<div class="phone-head"><button id="phoneHome" aria-label="Phone home">‹</button><span>ABUAD LIFE<span class="phone-time">${String(state.hour).padStart(2,'0')}:00</span></span><button id="phoneClose" aria-label="Close phone">×</button></div><div class="phone-body">${app==='home'?phoneHomeContent():`<div class="eyebrow">STUDENT PHONE · ${meta?.[1]||'✦'}</div><h2>${meta?.[2]||'My campus'}</h2><p>${meta?.[3]||''}</p>${phoneAppContent(app)}`}</div><div class="phone-footer">Single-player · fictional student life · virtual naira</div>`);$('#modal').classList.add('student-phone');$('#phoneHome').onclick=()=>openStudentPhone();$('#phoneClose').onclick=close;bindPhone(app)}
function phoneHomeContent(){const s=ensureStudentState();return `<div class="phone-welcome"><span>${state.avatar}</span><div><h2>Hey, ${escapeHtml(state.name)}.</h2><small>Day ${state.day} · ${money(state.money)} in your wallet</small></div></div><div class="phone-app-grid">${PHONE_APPS.map(([id,icon,name])=>`<button data-phone="${id}"><span>${icon}</span>${name}</button>`).join('')}</div><div class="phone-notices"><div class="section-label">LATEST IN YOUR STORY</div>${s.notices.length?s.notices.slice(0,3).map(n=>`<p>Day ${n.day} · ${escapeHtml(n.text)}</p>`).join(''):'<p>Explore your planner, find a club, and set a little aside for later.</p>'}</div>`}
function phoneAppContent(app){const s=ensureStudentState();if(app==='planner'){const lecture=places.find(p=>p.id===academicBuilding());return `<div class="phone-banner"><b>Your fictional day plan</b><p>${(state.day-1)%7<5?'09:00 · Course lecture<br>14:00 · Independent study':'Weekend · Revision, society activities & recovery'}<br>16:00 · ${[5,12,19,26].includes(state.day)?'Student showcase':'Free campus time'}</p>${phoneButton('Go to '+lecture.name,`data-go="${lecture.id}"`)}</div><p class="phone-note">A game timetable, not the real university schedule. Core lectures still count once per day.</p>${phoneButton(s.quizDays.includes(state.day)?'Revision quiz completed today ✓':'Revision quiz · 1 hr', 'id="quizStart"',s.quizDays.includes(state.day))}${phoneButton('Join student showcase · 1 hr · ₦200','id="showcase"')}<h3>Deadlines</h3>${projectList().map(p=>{const w=s.projects[p.id]||{};return `<div class="phone-row"><b>${p.title}</b><small>Due day ${p.due} · ${w.submitted?'Submitted ✓':state.day>p.due?'Deadline passed':(w.progress||0)+'/2 work sessions'}</small>${phoneButton('Work session · 2 hrs',`data-project="${p.id}"`,w.submitted||state.day>p.due||(w.progress||0)>=2)}${phoneButton('Submit · 1 hr',`data-submit="${p.id}"`,w.submitted||state.day>p.due||(w.progress||0)<2)}</div>`}).join('')}`}
if(app==='wallet')return `<div class="phone-balances"><div><small>SPENDABLE</small><h2>${money(state.money)}</h2></div><div><small>SAVINGS</small><h2>${money(s.savings)}</h2></div></div><p class="phone-note">Savings are a separate virtual balance with no interest, fees or real-world value. The allowance arrives on days 8, 15 and 22.</p><label for="savingsAmount">Move virtual naira</label><input id="savingsAmount" type="number" min="1" step="1" placeholder="Amount"><div class="phone-button-pair">${phoneButton('Save','id="depositSavings"')}${phoneButton('Withdraw','id="withdrawSavings"')}</div><div class="phone-row"><b>Fictional merit award · ₦5,000</b><small>GPA 3.50+ · 8 lectures · 1 planner project submitted</small>${phoneButton(s.scholarship?'Award received ✓':'Check eligibility & claim','id="meritAward"',s.scholarship)}</div><h3>Wallet history</h3>${s.ledger.length?s.ledger.slice(0,15).map(t=>`<div class="ledger-row"><div><b>${escapeHtml(t.text)}</b><small>Day ${t.day} · ${String(t.hour).padStart(2,'0')}:00</small></div><strong class="${t.amount>0?'credit':''}">${t.amount>0?'+':''}${money(t.amount)}</strong></div>`).join(''):'<p>Your new wallet transactions will appear here.</p>'}`;
if(app==='needs')return `<div class="phone-need-grid">${[['Energy',state.energy],['Hunger',state.hunger],['Mood',state.mood],['Social',state.social],['Hygiene',s.hygiene],['Bathroom comfort',s.bladder]].map(([n,v])=>`<div><label>${n}<b>${Math.round(v)}%</b></label><div class="bar"><span style="width:${v}%;background:${v<20?'#c78865':'#7ea56f'}"></span></div></div>`).join('')}</div><p>Needs change as game hours pass. Hygiene and bathroom comfort below 15 lower your mood. Nothing decays while the game is closed.</p>${phoneButton('Bathroom break · 1 hr','data-care="bathroom"')}${phoneButton('Shower at a hostel · 1 hr','data-care="shower"')}${phoneButton('Quiet wellbeing break · 1 hr','data-care="rest"')}`;
if(app==='messages')return `<p class="phone-note">Conversations with fictional NPCs. One reply per friend per day. This is not live chat.</p>${people.map((p,i)=>`<div class="phone-row"><b>${p.icon} ${p.name}</b><p>${i===0?'I have a tiny project idea. Want to brainstorm?':i===1?'Ready to revise together? We can start with the difficult part.':'Come for a quick catch-up? Campus is better with company.'}</p>${phoneButton(state.daily['message'+i]?'Replied today ✓':i===0?'Let’s make something · 1 hr':i===1?'Let’s revise · 1 hr':'Let’s catch up · 1 hr',`data-message="${i}"`,state.daily['message'+i])}</div>`).join('')}`;
if(app==='gigs')return `<div class="pill">${Math.round(state.skills)} skill points · 1 phone gig per day</div>${STUDENT_GIGS.map(g=>`<div class="phone-row"><b>${g.icon} ${g.title}</b><p>${g.text}</p><small>${g.hours} hrs · ${g.skill} skill points required · earns ${money(g.pay)}</small>${phoneButton(state.daily.studentGig?'Gig completed today ✓':state.skills<g.skill?'Build your skills to unlock':'Take this gig',`data-gig="${g.id}"`,state.daily.studentGig||state.skills<g.skill)}</div>`).join('')}`;
if(app==='shop')return `<p class="phone-note">All purchases use virtual naira. Food goes into your bag; room items and outfits are permanent for this playthrough.</p>${STUDENT_ITEMS.map(i=>`<div class="phone-shop-item"><span>${i.icon}</span><div><b>${i.name}</b><small>${i.text}</small><strong>${money(i.price)}</strong></div><button data-buy="${i.id}" ${state.finished||s.owned.includes(i.id)?'disabled':''}>${s.owned.includes(i.id)?'Owned':'Buy'}</button></div>`).join('')}`;
if(app==='bag'){const items=STUDENT_ITEMS.filter(i=>(s.inventory[i.id]||0)>0);return items.length?items.map(i=>`<div class="phone-row"><b>${i.icon} ${i.name} × ${s.inventory[i.id]}</b><small>${i.text}</small>${phoneButton('Use · 1 hr',`data-use="${i.id}"`)}</div>`).join(''):'<div class="empty">Your bag is empty. Pick up a few essentials in the Campus shop.</div>'}
if(app==='wardrobe')return `<div class="outfit-preview">${state.avatar}<span>${s.outfit==='default'?'🎓':STUDENT_ITEMS.find(i=>i.id===s.outfit)?.icon||'🎓'}</span><b>${escapeHtml(state.name)}</b></div><p>Outfits change your campus profile appearance.</p>${[{id:'default',name:'Freshers’ essentials',icon:'🎓'},...STUDENT_ITEMS.filter(i=>i.kind==='outfit'&&s.owned.includes(i.id))].map(i=>phoneButton((s.outfit===i.id?'Wearing ✓ · ':'Wear · ')+i.icon+' '+i.name,`data-equip="${i.id}"`,s.outfit===i.id)).join('')}`;
if(app==='room')return `<div class="hostel-scene"><span class="room-window">☀</span><span class="room-bed">${s.owned.includes('bed')?'🛏️':'🛌'}</span>${s.owned.includes('desk')?'<span class="room-desk">🪑💡📚</span>':''}${s.owned.includes('plants')?'<span class="room-plant">🪴🖼️</span>':''}</div><h3>Your hostel corner</h3><p>One student room, made your own. Upgrades affect naps, study sessions, and your next morning.</p>${STUDENT_ITEMS.filter(i=>i.kind==='room').map(i=>`<div class="phone-row"><b>${i.icon} ${i.name}</b><small>${i.text}</small>${phoneButton(s.owned.includes(i.id)?'Installed ✓':'Buy for '+money(i.price),`data-buy="${i.id}"`,s.owned.includes(i.id))}</div>`).join('')}`;
if(app==='clubs')return s.club?`<div class="phone-banner"><h3>${STUDENT_CLUBS.find(c=>c.id===s.club).icon} ${STUDENT_CLUBS.find(c=>c.id===s.club).name}</h3><p>${s.clubPoints} meetups attended · ${s.clubPoints>=3?'Established member':'New member'}</p>${phoneButton(state.daily.club?'Met up today ✓':'Attend a meetup · 2 hrs','id="clubMeetup"',state.daily.club)}</div><p>One club per semester. These are fictional student societies.</p>`:`<p>Choose one fictional society for this semester. Meetups develop your skills, mood and social life.</p>${STUDENT_CLUBS.map(c=>`<div class="phone-row"><b>${c.icon} ${c.name}</b><p>${c.text}</p>${phoneButton('Join this society',`data-club="${c.id}"`)}</div>`).join('')}`;
if(app==='achievements'){const all=[['firstlecture','🎓','First lecture','Attend your first lecture.'],['saver','💰','A little safety net','Save ₦3,000.'],['home','🛏️','A room of my own','Own two room upgrades.'],['club','🤝','Found my community','Attend three club meetups.'],['deadlines','📅','Ahead of the deadline','Submit two planner projects.'],['scholar','🏅','Scholarship ready','Earn the fictional merit award.'],['friendship','💬','A friend to count on','Reach friendship level three.'],['explorer','🧭','Campus explorer','Take activities at 10 mapped places.']];return `<span class="pill">${s.reputation} campus reputation · ${s.achievements.length} / 8 milestones</span>${all.map(([id,icon,title,desc])=>`<div class="phone-row ${s.achievements.includes(id)?'milestone-done':''}"><b>${icon} ${title} ${s.achievements.includes(id)?'✓':''}</b><small>${desc}</small></div>`).join('')}`}
if(app==='settings')return `<div class="outfit-preview">${state.avatar}<b>${escapeHtml(state.name)}</b></div><label for="studentBio">Your campus bio</label><textarea id="studentBio" maxlength="120" rows="3">${escapeHtml(s.profileBio)}</textarea>${phoneButton('Save my bio','id="saveBio"')}<p class="phone-note">Your progress belongs to this browser. This edition is single-player; friends and messages are fictional NPC interactions.</p>`;return ''}
function bindPhone(app){document.querySelectorAll('[data-phone]').forEach(b=>b.onclick=()=>openStudentPhone(b.dataset.phone));for(const[attr,fn]of [['buy',buyStudentItem],['use',useStudentItem],['equip',equipStudentOutfit],['care',studentCare],['gig',studentGig],['club',joinStudentClub],['project',workStudentProject],['submit',submitStudentProject]])document.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>fn(b.dataset[attr]));document.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>studentMessage(Number(b.dataset.message),Number(b.dataset.message)===0?'create':Number(b.dataset.message)===1?'study':'social'));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{close();tab='campus';selectPlace(b.dataset.go)});if(app==='wallet'){$('#depositSavings').onclick=()=>studentSavings('deposit',$('#savingsAmount').value);$('#withdrawSavings').onclick=()=>studentSavings('withdraw',$('#savingsAmount').value);$('#meritAward').onclick=claimStudentScholarship}if(app==='planner'){$('#quizStart').onclick=startStudentQuiz;$('#showcase').onclick=studentEvent}if(app==='clubs'&&ensureStudentState().club)$('#clubMeetup').onclick=meetStudentClub;if(app==='settings')$('#saveBio').onclick=()=>{ensureStudentState().profileBio=$('#studentBio').value.trim().slice(0,120);studentCommit('Updated your campus bio.','settings')}}
function renderStudentLife(){const s=ensureStudentState();const needs=$('#studentNeeds');if(needs){needs.innerHTML=[['Social',state.social,'💬'],['Hygiene',s.hygiene,'🫧'],['Bathroom',s.bladder,'🚿']].map(([n,v,i])=>`<button data-open-needs><span>${i} ${n}</span><b>${Math.round(v)}%</b><span class="bar"><span style="width:${v}%;background:${v<20?'#c78865':'#83a579'}"></span></span></button>`).join('');document.querySelectorAll('[data-open-needs]').forEach(b=>b.onclick=()=>openStudentPhone('needs'))}const outfit=STUDENT_ITEMS.find(i=>i.id===s.outfit);if(outfit){const av=$('#profile .avatar');if(av)av.innerHTML=state.avatar+`<span class="profile-outfit">${outfit.icon}</span>`}if(tab==='life'){disposeGeoMap();$('#greeting').textContent='There’s a life between lectures.';$('#content').innerHTML=`<div class="student-life-hero"><div><span class="eyebrow">YOUR STUDENT LIFE</span><h2>More than making the grade.</h2><p>Build your routine, find your people, and make your little corner of campus your own.</p><button class="primary" id="launchPhone">Open my student phone →</button></div><div class="hero-phone">📱<span>${state.avatar}</span></div></div><div class="life-app-cards">${PHONE_APPS.slice(0,11).map(([id,icon,name,text])=>`<button data-phone="${id}"><span>${icon}</span><h3>${name}</h3><p>${text}</p><b>Open →</b></button>`).join('')}</div><div class="log"><small>YOUR CAMPUS BIO</small>${escapeHtml(s.profileBio)}</div>`;$('#launchPhone').onclick=()=>openStudentPhone();document.querySelectorAll('[data-phone]').forEach(b=>b.onclick=()=>openStudentPhone(b.dataset.phone))}}
